    fn build_command(&self, command: &str) -> Command {
        if cfg!(windows) {
            let mut cmd = Command::new(windows_shell_program());
            let ps_script = format!("$ProgressPreference='SilentlyContinue';{command}");
            cmd.args([
                "-NoLogo",
                "-NoProfile",
                "-NonInteractive",
                "-ExecutionPolicy",
                "Bypass",
                "-Command",
                &ps_script,
            ]);
            cmd
        } else {
            let mut cmd = Command::new("sh");
            cmd.arg("-c").arg(command);
            cmd
        }
    }

    fn merged_env(&self, env: Option<&HashMap<String, String>>) -> HashMap<String, String> {
        let mut merged: HashMap<String, String> = std::env::vars().collect();
        if let Some(extra) = env {
            for (k, v) in extra {
                merged.insert(k.clone(), v.clone());
            }
        }
        merged
    }

    fn spawn_reader(
        stream: impl tokio::io::AsyncRead + Unpin + Send + 'static,
        state: Arc<Mutex<HandleState>>,
    ) -> JoinHandle<()> {
        tokio::spawn(async move {
            let mut reader = BufReader::new(stream);
            let mut buf = Vec::new();
            loop {
                buf.clear();
                match reader.read_until(b'\n', &mut buf).await {
                    Ok(0) => break,
                    Ok(_) => {
                        let mut s = lock_state(&state);
                        s.output_lines.push(decode_output_chunk(&buf));
                    }
                    Err(_) => break,
                }
            }
        })
    }

    fn spawn_watcher(
        child: Arc<AsyncMutex<Option<Child>>>,
        readers: Vec<JoinHandle<()>>,
        state: Arc<Mutex<HandleState>>,
        done: Arc<Notify>,
    ) {
        tokio::spawn(async move {
            let status = {
                let mut guard = child.lock().await;
                match guard.as_mut() {
                    Some(c) => c.wait().await.ok(),
                    None => None,
                }
            };
            for reader in readers {
                let _ = reader.await;
            }
            let exit_code = status.and_then(|s| s.code());
            {
                let mut s = lock_state(&state);
                s.exit_code = exit_code;
                s.finished = true;
            }
            done.notify_waiters();
        });
    }
}

