/// One terminal command run. Mirror of Python's `TerminalSession`.
pub struct TerminalSession {
    session_id: String,
    executor: TerminalExecutor,
    command: String,
    env: Option<HashMap<String, String>>,
    timeout: f64,
    handle: Option<TerminalHandle>,
    final_output_lines: Option<Vec<String>>,
    final_payload: Option<Map<String, Value>>,
}

impl TerminalSession {
    pub fn new(
        session_id: impl Into<String>,
        executor: TerminalExecutor,
        command: impl Into<String>,
        env: Option<HashMap<String, String>>,
        timeout: f64,
    ) -> Self {
        let command_text = command.into().trim().to_string();
        Self {
            session_id: session_id.into(),
            executor,
            command: command_text,
            env: normalize_env(env),
            timeout: positive_float(timeout, 30.0),
            handle: None,
            final_output_lines: None,
            final_payload: None,
        }
    }

    async fn running_snapshot(
        &self,
        handle: &TerminalHandle,
        tail_line_num: usize,
        message: Option<&str>,
    ) -> Value {
        let mut payload = Map::new();
        payload.insert("id".to_string(), Value::String(self.session_id.clone()));
        payload.insert("runtime".to_string(), self.runtime("running"));
        payload.insert("status".to_string(), Value::String("running".to_string()));
        payload.insert("done".to_string(), Value::Bool(false));
        let output = self.executor.snapshot_output(handle, tail_line_num).await;
        if let Value::Object(obj) = output {
            for (k, v) in obj {
                payload.insert(k, v);
            }
        }
        if let Some(msg) = message {
            payload.insert("message".to_string(), Value::String(msg.to_string()));
        }
        Value::Object(payload)
    }

    async fn finalize(&mut self, tail_line_num: usize) -> Value {
        let handle = match &self.handle {
            Some(h) => h,
            None => return Value::Null,
        };
        let (status, exit_code, output_lines) = {
            let state = lock_state(&handle.state);
            let status = if state.killed {
                "killed"
            } else if state.exit_code == Some(0) {
                "completed_success"
            } else {
                "completed_error"
            };
            (status, state.exit_code, state.output_lines.clone())
        };
        self.final_output_lines = Some(output_lines.clone());

        let mut payload = Map::new();
        payload.insert("id".to_string(), Value::String(self.session_id.clone()));
        payload.insert("runtime".to_string(), self.runtime(status));
        payload.insert("status".to_string(), Value::String(status.to_string()));
        payload.insert("done".to_string(), Value::Bool(true));
        payload.insert(
            "exit_code".to_string(),
            exit_code
                .map(|v| Value::Number(v.into()))
                .unwrap_or(Value::Null),
        );
        self.insert_output(&mut payload, &output_lines, tail_line_num);

        self.final_payload = Some(payload.clone());
        Value::Object(payload)
    }

    fn slice_final(&self, mut payload: Map<String, Value>, tail_line_num: usize) -> Value {
        let output_lines = self.final_output_lines.clone().unwrap_or_default();
        self.insert_output(&mut payload, &output_lines, tail_line_num);
        let status = payload
            .get("status")
            .and_then(Value::as_str)
            .unwrap_or("completed")
            .to_string();
        payload.insert("runtime".to_string(), self.runtime(&status));
        Value::Object(payload)
    }

    fn insert_output(
        &self,
        payload: &mut Map<String, Value>,
        output_lines: &[String],
        tail_line_num: usize,
    ) {
        let output = tail_output(output_lines, tail_line_num);
        payload.insert("output".to_string(), Value::String(output.concat()));
        payload.insert(
            "returned_lines".to_string(),
            Value::Number(output.len().into()),
        );
        payload.insert(
            "total_lines".to_string(),
            Value::Number(output_lines.len().into()),
        );
    }

    fn runtime(&self, status: &str) -> Value {
        json!({
            "kind": "terminal",
            "id": self.session_id,
            "status": status,
        })
    }

