#[async_trait]
impl ToolSession for TerminalSession {
    fn session_id(&self) -> &str {
        &self.session_id
    }

    fn capabilities(&self) -> HashSet<Cap> {
        let mut caps = HashSet::new();
        caps.insert(Cap::Checkout);
        caps
    }

    async fn start(&mut self, _args: &ToolArgs) -> Result<Value> {
        if self.handle.is_some() {
            return self.checkout(_args).await;
        }
        match self.executor.exec(&self.command, self.env.as_ref()).await {
            Ok(handle) => {
                self.handle = Some(handle);
            }
            Err(exc) => {
                return Ok(json!({
                    "id": self.session_id,
                    "runtime": self.runtime("completed_error"),
                    "status": "completed_error",
                    "done": true,
                    "error": exc.to_string(),
                }));
            }
        }
        self.wait_for_start(self.timeout).await
    }

    async fn checkout(&mut self, args: &ToolArgs) -> Result<Value> {
        let tail_line_num = args
            .get("tail_line_num")
            .and_then(Value::as_u64)
            .map(|v| v as usize)
            .filter(|v| *v > 0)
            .unwrap_or(DEFAULT_TAIL_LINE_NUM);
        if let Some(payload) = &self.final_payload {
            return Ok(self.slice_final(payload.clone(), tail_line_num));
        }
        let handle = self
            .handle
            .as_ref()
            .ok_or_else(|| anyhow!("terminal session has not started"))?;
        if lock_state(&handle.state).finished {
            return Ok(self.finalize(tail_line_num).await);
        }
        let handle = self.handle.as_ref().unwrap();
        Ok(self.running_snapshot(handle, tail_line_num, None).await)
    }

    async fn cancel(&mut self) -> Result<()> {
        if self.final_payload.is_some() {
            return Ok(());
        }
        let Some(handle) = &self.handle else {
            return Ok(());
        };
        let _ = self.executor.kill(handle).await;
        let _ = self.executor.wait(handle, 2.0).await;
        let _ = self.finalize(DEFAULT_TAIL_LINE_NUM).await;
        Ok(())
    }

    fn is_done(&self) -> bool {
        if self.final_payload.is_some() {
            return true;
        }
        self.handle
            .as_ref()
            .map(|h| lock_state(&h.state).finished)
            .unwrap_or(false)
    }

    fn list_item(&self) -> Value {
        let status = self.list_status_sync();
        json!({
            "id": self.session_id,
            "kind": "terminal",
            "status": status,
            "done": self.is_done(),
        })
    }
}

