        }
    }

    fn merged_env(&self, env: Option<&HashMap<String, String>>) -> HashMap<String, String> {
        let mut merged: HashMap<String, String> = std::env::vars().collect();
        if let Some(extra) = env {
            for (k, v) in extra {
                merged.insert(k.clone(), v.clone());
            }
